type Manifest = {
  schemaVersion: 1;
  id: string;
  version: string;
  minecraft: string;
  loader: string;
  serverAddress: string;
  basePack: { source: "modrinth" | "curseforge"; url: string };
  overlay: Array<{ path: string; sha256: string; size: number }>;
};

// `Env` is generated by `wrangler types`. Secrets are intentionally absent
// from generated config, so only the secret is added to this narrow extension.
type PublisherEnv = Env & { PUBLISHER_TOKEN: string };
const safeSegment = /^[a-z0-9][a-z0-9._-]{0,79}$/i;
const safePath = /^[a-z0-9][a-z0-9._/-]{0,299}$/i;

function json(value: unknown, status = 200): Response {
  return Response.json(value, { status, headers: { "Cache-Control": "no-store" } });
}

async function authorized(request: Request, env: PublisherEnv): Promise<boolean> {
  const provided = request.headers.get("authorization")?.replace(/^Bearer\s+/i, "") ?? "";
  const encoder = new TextEncoder();
  const [left, right] = await Promise.all([
    crypto.subtle.digest("SHA-256", encoder.encode(provided)),
    crypto.subtle.digest("SHA-256", encoder.encode(env.PUBLISHER_TOKEN)),
  ]);
  return crypto.subtle.timingSafeEqual(left, right);
}

function objectKey(id: string, version: string, path: string): string | null {
  if (!safeSegment.test(id) || !safeSegment.test(version) || !safePath.test(path) || path.includes("..")) return null;
  return `packs/${id}/${version}/${path}`;
}

function validManifest(value: unknown, id: string, version: string): value is Manifest {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const manifest = value as Partial<Manifest>;
  return manifest.schemaVersion === 1 && manifest.id === id && manifest.version === version
    && typeof manifest.minecraft === "string" && typeof manifest.loader === "string"
    && typeof manifest.serverAddress === "string" && !!manifest.basePack
    && (manifest.basePack.source === "modrinth" || manifest.basePack.source === "curseforge")
    && typeof manifest.basePack.url === "string" && Array.isArray(manifest.overlay)
    && manifest.overlay.every((file) => safePath.test(file.path) && !file.path.includes("..") && /^[a-f0-9]{64}$/i.test(file.sha256) && Number.isInteger(file.size) && file.size >= 0);
}

async function publishFile(request: Request, env: PublisherEnv, id: string, version: string, filePath: string): Promise<Response> {
  const key = objectKey(id, version, `overlay/${filePath}`);
  if (!key || !request.body) return json({ error: "Ruta o contenido inválido" }, 400);
  const length = Number(request.headers.get("content-length") ?? 0);
  if (!Number.isFinite(length) || length > 100 * 1024 * 1024) return json({ error: "Archivo demasiado grande" }, 413);
  const sha256 = request.headers.get("x-tenso-sha256");
  if (!sha256 || !/^[a-f0-9]{64}$/i.test(sha256)) return json({ error: "Falta el hash SHA-256" }, 422);
  await env.PACK_CONTENT.put(key, request.body, { httpMetadata: { contentType: request.headers.get("content-type") ?? "application/octet-stream" }, customMetadata: { sha256 } });
  console.log(JSON.stringify({ message: "overlay uploaded", id, version, key }));
  return json({ uploaded: true }, 201);
}

async function publishManifest(request: Request, env: PublisherEnv, id: string, version: string): Promise<Response> {
  let manifest: unknown;
  try { manifest = await request.json(); } catch { return json({ error: "JSON inválido" }, 400); }
  if (!validManifest(manifest, id, version)) return json({ error: "Manifiesto inválido" }, 422);
  const key = objectKey(id, version, "manifest.json");
  if (!key) return json({ error: "Ruta inválida" }, 400);
  await env.PACK_CONTENT.put(key, JSON.stringify(manifest), { httpMetadata: { contentType: "application/json; charset=utf-8" } });
  return json({ uploaded: true }, 201);
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    const match = url.pathname.match(/^\/v1\/(admin\/)?packs\/([^/]+)(?:\/([^/]+))?(?:\/(.*))?$/);
    if (!match) return json({ error: "No encontrado" }, 404);
    const [, admin, id, version, tail = ""] = match;
    if (!safeSegment.test(id) || (version && !safeSegment.test(version))) return json({ error: "Identificador inválido" }, 400);
    try {
      if (admin) {
        if (!(await authorized(request, env))) return json({ error: "No autorizado" }, 401);
        if (!version) return json({ error: "Falta la versión" }, 400);
        if (request.method === "PUT" && tail.startsWith("files/")) return publishFile(request, env, id, version, tail.slice(6));
        if (request.method === "PUT" && tail === "manifest") return publishManifest(request, env, id, version);
        if (request.method === "POST" && tail === "promote") {
          const manifest = await env.PACK_CONTENT.head(objectKey(id, version, "manifest.json")!);
          if (!manifest) return json({ error: "Primero publica el manifiesto" }, 409);
          await env.PACK_CONTENT.put(`packs/${id}/latest.json`, JSON.stringify({ version }), { httpMetadata: { contentType: "application/json; charset=utf-8" } });
          return json({ promoted: true });
        }
      } else if (request.method === "GET" && !version && tail === "latest") {
        const latest = await env.PACK_CONTENT.get(`packs/${id}/latest.json`);
        return latest ? new Response(latest.body, { headers: { "content-type": "application/json", "cache-control": "no-store" } }) : json({ error: "Pack no publicado" }, 404);
      } else if (request.method === "GET" && version && tail) {
        const key = objectKey(id, version, tail);
        const object = key ? await env.PACK_CONTENT.get(key) : null;
        return object ? new Response(object.body, { headers: { "content-type": object.httpMetadata?.contentType ?? "application/octet-stream", "cache-control": "public, max-age=3600" } }) : json({ error: "Archivo no encontrado" }, 404);
      }
      return json({ error: "Ruta no soportada" }, 405);
    } catch (error) {
      console.error(JSON.stringify({ message: "publisher request failed", path: url.pathname, error: error instanceof Error ? error.message : String(error) }));
      return json({ error: "Error interno" }, 500);
    }
  },
} satisfies ExportedHandler<PublisherEnv>;
